            <input type="checkbox" id="evidenceFlag">
            <span>Missing evidence, source, date, or proof snippet</span>
          </label>
        </div>

        <textarea class="note-area" id="cardNote" placeholder="Optional update note for this card. Example: verify 2026 pricing page and add source date."></textarea>
      </div>
    </section>

    <section class="panel" aria-labelledby="flagTitle">
      <h2 class="panel-title" id="flagTitle">Flagged cards</h2>
      <div class="mini-list" id="flagList"></div>
