    <section class="panel" aria-labelledby="updateTitle">
      <h2 class="panel-title" id="updateTitle">Copy or download update list</h2>
      <div class="output-box" id="updateOutput" aria-live="polite"></div>
      <div class="btn-grid">
        <button class="primary" id="copyBtn">Copy update list</button>
        <button id="downloadBtn">Download .txt</button>
      </div>
      <p class="small-status" id="copyStatus" aria-live="polite"></p>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      var STORAGE_KEY = "faq_flashcard_reviewer_v1";

      var state = {
        cards: [],
        index: 0,
        showingAnswer: false
      };

      var sampleText = [
        "Q: How often should this FAQ be reviewed?",
        "A: Review any answer with prices, dates, product details, legal rules, policy language, or statistics at least quarterly.",
        "",
        "Q: What counts as missing evidence?",
        "A: A claim is missing evidence when it makes a factual promise but does not point to a source, date, internal note, report, policy page, or proof snippet.",
        "",
        "Q: What makes a claim stale?",
        "A: Claims using phrases like currently, latest, this year, recently, or now should be checked because they can age quickly."
      ].join("\n");

      var els = {
        faqInput: document.getElementById("faqInput"),
        parseBtn: document.getElementById("parseBtn"),
        sampleBtn: document.getElementById("sampleBtn"),
        saveBtn: document.getElementById("saveBtn"),
        clearBtn: document.getElementById("clearBtn"),
        saveStatus: document.getElementById("saveStatus"),
        scoreLabel: document.getElementById("scoreLabel"),
        meterFill: document.getElementById("meterFill"),
        scoreBig: document.getElementById("scoreBig"),
        deckCount: document.getElementById("deckCount"),
        scoreExplain: document.getElementById("scoreExplain"),
        emptyState: document.getElementById("emptyState"),
        reviewArea: document.getElementById("reviewArea"),
        cardSide: document.getElementById("cardSide"),
        cardText: document.getElementById("cardText"),
        progressText: document.getElementById("progressText"),
        prevBtn: document.getElementById("prevBtn"),
        flipBtn: document.getElementById("flipBtn"),
        nextBtn: document.getElementById("nextBtn"),
        shuffleBtn: document.getElementById("shuffleBtn"),
        staleFlag: document.getElementById("staleFlag"),
        evidenceFlag: document.getElementById("evidenceFlag"),
        cardNote: document.getElementById("cardNote"),
        flagList: document.getElementById("flagList"),
        updateOutput: document.getElementById("updateOutput"),
        copyBtn: document.getElementById("copyBtn"),
        downloadBtn: document.getElementById("downloadBtn"),
        copyStatus: document.getElementById("copyStatus")
      };

      function normalizeText(text) {
        return String(text || "")
          .replace(/\r\n/g, "\n")
          .replace(/\r/g, "\n")
          .trim();
      }

      function stripLabel(line, label) {
        var re = label === "q"
          ? /^\s*(q|question)\s*[:\-]\s*/i
          : /^\s*(a|answer)\s*[:\-]\s*/i;
        return String(line || "").replace(re, "").trim();
      }

      function parseLabeledBlock(block) {
        var lines = block.split("\n");
        var q = [];
        var a = [];
        var mode = "";
        lines.forEach(function (line) {
          if (/^\s*(q|question)\s*[:\-]/i.test(line)) {
            mode = "q";
            q.push(stripLabel(line, "q"));
          } else if (/^\s*(a|answer)\s*[:\-]/i.test(line)) {
            mode = "a";
            a.push(stripLabel(line, "a"));
          } else if (mode === "q") {
            q.push(line.trim());
          } else if (mode === "a") {
            a.push(line.trim());
          }
        });
        return {
          question: q.join("\n").trim(),
          answer: a.join("\n").trim()
        };
      }

      function splitFirst(text, separator) {
        var i = text.indexOf(separator);
        if (i < 0) return null;
        return [
          text.slice(0, i).trim(),
          text.slice(i + separator.length).trim()
        ];
      }

      function parseFaqText(raw) {
        var text = normalizeText(raw);
        if (!text) return [];

        var cards = [];
        var blocks = text.split(/\n\s*\n+/);

        blocks.forEach(function (block) {
          var clean = block.trim();
          if (!clean) return;

          var parsed = null;

          if (/^\s*(q|question)\s*[:\-]/im.test(clean) && /^\s*(a|answer)\s*[:\-]/im.test(clean)) {
            parsed = parseLabeledBlock(clean);
          } else if (clean.indexOf("\t") > -1) {
            var tabSplit = splitFirst(clean, "\t");
            if (tabSplit) parsed = { question: tabSplit[0], answer: tabSplit[1] };
          } else if (clean.indexOf(" | ") > -1) {
            var pipeSplit = splitFirst(clean, " | ");
            if (pipeSplit) parsed = { question: pipeSplit[0], answer: pipeSplit[1] };
          } else {
            var lines = clean.split("\n").map(function (line) { return line.trim(); }).filter(Boolean);
            if (lines.length >= 2) {
              parsed = { question: lines[0], answer: lines.slice(1).join("\n") };
            }
          }

          if (parsed && parsed.question && parsed.answer) {
            cards.push({
              id: makeId(),
              question: parsed.question,
              answer: parsed.answer,
              stale: false,
              missingEvidence: false,
              note: ""
            });
          }
        });

        return cards;
      }

      function makeId() {
        return String(Date.now()) + "_" + Math.random().toString(16).slice(2);
      }

      function currentCard() {
        if (!state.cards.length) return null;
        if (state.index < 0) state.index = 0;
        if (state.index >= state.cards.length) state.index = state.cards.length - 1;
        return state.cards[state.index];
      }

      function getFreshnessCues(card) {
        var text = ((card.question || "") + " " + (card.answer || "")).toLowerCase();
        var cues = [];
        [
          "currently",
          "latest",
          "recently",
          "now",
          "today",
          "this year",
          "new",
          "updated",
          "expected",
          "will",
          "soon",
          "as of"
        ].forEach(function (cue) {
          if (text.indexOf(cue) > -1) cues.push(cue);
        });

        var yearMatches = text.match(/\b(20[0-9]{2})\b/g) || [];
        var thisYear = new Date().getFullYear();
        var oldYears = [];
        yearMatches.forEach(function (yearText) {
          var year = Number(yearText);
          if (year <= thisYear - 2 && oldYears.indexOf(year) === -1) {
            oldYears.push(year);
          }
        });
        oldYears.sort();
        oldYears.forEach(function (year) {
          cues.push(String(year));
        });

        return cues.slice(0, 6);
      }

      function scoreCard(card) {
        if (!card) return 0;
        var score = 100;
        var cues = getFreshnessCues(card);

        if (!card.answer || card.answer.trim().length < 8) score -= 30;
        if (card.stale) score -= 38;
        if (card.missingEvidence) score -= 28;
        if (cues.length) score -= Math.min(18, cues.length * 6);
        if (card.note && card.note.trim().length > 0) score -= 4;

        return Math.max(0, Math.min(100, Math.round(score)));
      }

      function deckScore() {
        if (!state.cards.length) return 0;
        var total = state.cards.reduce(function (sum, card) {
          return sum + scoreCard(card);
        }, 0);
        return Math.round(total / state.cards.length);
      }

      function statusText(score) {
        if (score >= 85) return "Strong. Few obvious freshness risks.";
        if (score >= 65) return "Usable, but some answers need verification.";
        if (score >= 40) return "Review needed before publishing.";
        return "High-risk deck. Prioritize updates before reuse.";
      }

      function flaggedCards() {
        return state.cards.filter(function (card) {
          return card.stale || card.missingEvidence || card.note.trim() || getFreshnessCues(card).length;
        });
      }

      function buildUpdateList() {
        var score = deckScore();
        var lines = [];
        var flagged = flaggedCards();

        lines.push("FAQ update list");
        lines.push("Freshness score: " + score + "/100");
        lines.push("Cards reviewed: " + state.cards.length);
        lines.push("");

        if (!state.cards.length) {
          lines.push("No cards built yet.");
          return lines.join("\n");
        }

        if (!flagged.length) {
          lines.push("No flagged items yet.");
          lines.push("Suggested next step: spot-check source dates for any answer with pricing, legal, policy, product, or statistical claims.");
          return lines.join("\n");
        }

        flagged.forEach(function (card, idx) {
          var flags = [];
          var cues = getFreshnessCues(card);

          if (card.stale) flags.push("stale claim");
          if (card.missingEvidence) flags.push("missing evidence");
          if (cues.length) flags.push("time-sensitive cue: " + cues.join(", "));
          if (card.note.trim()) flags.push("review note");

          lines.push(String(idx + 1) + ". " + card.question);
          lines.push("   Flags: " + flags.join("; "));
          lines.push("   Action: verify the answer, add source/date/proof, and rewrite any outdated wording.");
          if (card.note.trim()) {
            lines.push("   Note: " + card.note.trim());
          }
          lines.push("");
        });

        return lines.join("\n").trim();
      }

      function saveToLocal(message) {
        try {
          var payload = {
            input: els.faqInput.value,
            cards: state.cards,
            index: state.index,
            showingAnswer: state.showingAnswer
          };
          localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
          if (message) setStatus(els.saveStatus, message);
        } catch (err) {
          setStatus(els.saveStatus, "Could not save locally in this browser.");
        }
      }

      function loadFromLocal() {
        try {
          var raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return false;
          var payload = JSON.parse(raw);
          els.faqInput.value = payload.input || "";
          state.cards = Array.isArray(payload.cards) ? payload.cards : [];
          state.index = Number(payload.index) || 0;
          state.showingAnswer = Boolean(payload.showingAnswer);
          return true;
        } catch (err) {
          return false;
        }
      }

      function setStatus(el, text) {
        el.textContent = text;
        window.clearTimeout(el._timer);
        el._timer = window.setTimeout(function () {
          el.textContent = "";
        }, 2500);
      }

      function syncCurrentCardFromControls() {
        var card = currentCard();
        if (!card) return;
        card.stale = els.staleFlag.checked;
        card.missingEvidence = els.evidenceFlag.checked;
        card.note = els.cardNote.value;
      }

      function render() {
        var hasCards = state.cards.length > 0;
        var card = currentCard();
        var score = deckScore();

        els.emptyState.hidden = hasCards;
        els.reviewArea.hidden = !hasCards;

        els.scoreLabel.textContent = score + "/100";
        els.scoreBig.textContent = String(score);
        els.meterFill.style.width = score + "%";
        els.deckCount.textContent = state.cards.length === 1 ? "1 card" : state.cards.length + " cards";
        els.scoreExplain.textContent = statusText(score);

        if (card) {
          els.cardSide.textContent = state.showingAnswer ? "Answer" : "Question";
          els.cardText.textContent = state.showingAnswer ? card.answer : card.question;
          els.progressText.textContent = "Card " + (state.index + 1) + " of " + state.cards.length + " · Card score " + scoreCard(card) + "/100";
          els.staleFlag.checked = Boolean(card.stale);
          els.evidenceFlag.checked = Boolean(card.missingEvidence);
          els.cardNote.value = card.note || "";
        } else {
          els.cardText.textContent = "";
          els.progressText.textContent = "";
          els.staleFlag.checked = false;
          els.evidenceFlag.checked = false;
          els.cardNote.value = "";
        }

        renderFlagList();
        els.updateOutput.textContent = buildUpdateList();
      }

      function renderFlagList() {
        var flagged = flaggedCards();
        els.flagList.textContent = "";

        if (!state.cards.length) {
          var emptyDeck = document.createElement("div");
          emptyDeck.className = "empty";
          emptyDeck.textContent = "Build cards to see flagged items.";
          els.flagList.appendChild(emptyDeck);
          return;
        }

        if (!flagged.length) {
          var none = document.createElement("div");
          none.className = "empty";
          none.textContent = "No flagged cards yet.";
          els.flagList.appendChild(none);
          return;
        }

        flagged.forEach(function (card) {
          var item = document.createElement("div");
          item.className = "mini-item";

          var q = document.createElement("p");
          q.textContent = card.question;

          var meta = document.createElement("p");
          meta.className = "tagline";

          var tags = [];
          if (card.stale) tags.push("stale");
          if (card.missingEvidence) tags.push("needs evidence");
          var cues = getFreshnessCues(card);
          if (cues.length) tags.push("cue: " + cues.join(", "));
          if (card.note.trim()) tags.push("note added");

          meta.textContent = tags.join(" · ");

          item.appendChild(q);
          item.appendChild(meta);
          els.flagList.appendChild(item);
        });
      }

      function buildCardsFromInput() {
        var parsed = parseFaqText(els.faqInput.value);
        state.cards = parsed;
        state.index = 0;
        state.showingAnswer = false;
        render();
        saveToLocal("Cards built and saved locally.");
        if (!parsed.length) {
          setStatus(els.saveStatus, "No usable Q&A pairs found. Try Q: and A: labels.");
        }
      }

      function moveCard(delta) {
        syncCurrentCardFromControls();
        if (!state.cards.length) return;
        state.index = (state.index + delta + state.cards.length) % state.cards.length;
        state.showingAnswer = false;
        render();
        saveToLocal("");
      }

      function shuffleCards() {
        syncCurrentCardFromControls();
        for (var i = state.cards.length - 1; i > 0; i--) {
          var j = Math.floor(Math.random() * (i + 1));
          var temp = state.cards[i];
          state.cards[i] = state.cards[j];
          state.cards[j] = temp;
        }
        state.index = 0;
        state.showingAnswer = false;
        render();
        saveToLocal("Shuffled and saved locally.");
      }

      function copyText(text) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          return navigator.clipboard.writeText(text);
        }

        return new Promise(function (resolve, reject) {
          var temp = document.createElement("textarea");
          temp.value = text;
          temp.setAttribute("readonly", "");
          temp.style.position = "fixed";
          temp.style.top = "0";
          temp.style.left = "0";
          document.body.appendChild(temp);
          temp.select();

          try {
            var ok = document.execCommand("copy");
            document.body.removeChild(temp);
            ok ? resolve() : reject(new Error("copy failed"));
          } catch (err) {
            document.body.removeChild(temp);
            reject(err);
          }
        });
      }

      function downloadText(filename, text) {
        var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.setTimeout(function () {
          URL.revokeObjectURL(url);
        }, 500);
      }

      els.parseBtn.addEventListener("click", buildCardsFromInput);

      els.sampleBtn.addEventListener("click", function () {
        els.faqInput.value = sampleText;
        buildCardsFromInput();
      });

      els.saveBtn.addEventListener("click", function () {
        syncCurrentCardFromControls();
        saveToLocal("Saved locally on this device.");
        render();
      });

      els.clearBtn.addEventListener("click", function () {
        localStorage.removeItem(STORAGE_KEY);
        state.cards = [];
        state.index = 0;
        state.showingAnswer = false;
        els.faqInput.value = "";
        render();
        setStatus(els.saveStatus, "Saved data cleared.");
      });

      els.prevBtn.addEventListener("click", function () {
        moveCard(-1);
      });

      els.nextBtn.addEventListener("click", function () {
        moveCard(1);
      });

      els.flipBtn.addEventListener("click", function () {
        syncCurrentCardFromControls();
        state.showingAnswer = !state.showingAnswer;
        render();
        saveToLocal("");
      });

      els.shuffleBtn.addEventListener("click", shuffleCards);

      els.staleFlag.addEventListener("change", function () {
        syncCurrentCardFromControls();
        render();
        saveToLocal("");
      });

      els.evidenceFlag.addEventListener("change", function () {
        syncCurrentCardFromControls();
        render();
        saveToLocal("");
      });

      els.cardNote.addEventListener("input", function () {
        syncCurrentCardFromControls();
        render();
        saveToLocal("");
      });

      els.faqInput.addEventListener("input", function () {
        saveToLocal("");
      });

      els.copyBtn.addEventListener("click", function () {
        var text = buildUpdateList();
        copyText(text).then(function () {
          setStatus(els.copyStatus, "Copied update list.");
        }).catch(function () {
          setStatus(els.copyStatus, "Copy failed. Select the update list and copy manually.");
        });
      });

      els.downloadBtn.addEventListener("click", function () {
        downloadText("faq-update-list.txt", buildUpdateList());
        setStatus(els.copyStatus, "Downloaded faq-update-list.txt.");
      });

      document.addEventListener("keydown", function (event) {
        var tag = document.activeElement && document.activeElement.tagName;
        var typing = tag === "TEXTAREA" || tag === "INPUT";
        if (typing) return;

        if (event.key === "ArrowLeft") moveCard(-1);
        if (event.key === "ArrowRight") moveCard(1);
        if (event.key === " " || event.key === "Enter") {
          event.preventDefault();
          state.showingAnswer = !state.showingAnswer;
          render();
        }
      });

      if (!loadFromLocal()) {
        state.cards = [];
      }

      render();
    }());
  </script>
</body>
</html>
